#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam2010B6. Variable R : realType. Let eqR := (@eq R). Variables A B C V W X Y Z U : 'rV[R]_2. Hypotheses (h_ABC_ncol : ~ colinear A B C) (h_AB : distmx A B = 30) (h_BC : distmx B C = 23) (h_CA : distmx C A = 27) (h_A_neq_B : A <> B) (h_B_neq_C : B <> C) (h_C_neq_A : C <> A) (h_V_on_AC : on_line V A C) (h_W_on_AC : on_line W A C) (h_V_between_AW : between V A W) (h_U_on_AB : on_line U A B) (h_Z_between_BU : between Z B U). Theorem segment_identity_area : exists area : R, area > 0. Proof. Admitted. End
